-- Ergon, demonstração local: assistências, funcionários, clientes, aparelhos,
-- orçamentos, ordens de serviço e pagamentos.
-- Executar uma vez em um banco PostgreSQL vazio. As exclusões de registros
-- relacionados são bloqueadas por chaves estrangeiras para preservar o histórico.

BEGIN;

CREATE TABLE public."AssistenciaTecnica" (
    "Id"        INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "Nome"      VARCHAR(255) NOT NULL,
    "Documento" VARCHAR(30) NOT NULL,
    "Email"     VARCHAR(255) NOT NULL,
    "Telefone"  VARCHAR(30),
    "Endereco"  VARCHAR(500),
    "Ativo"     BOOLEAN NOT NULL DEFAULT TRUE,

    CONSTRAINT "PK_IdAssistenciaTecnica" PRIMARY KEY ("Id"),
    CONSTRAINT "UQ_AssistenciaTecnica_Documento" UNIQUE ("Documento")
);

CREATE TABLE public."Funcionario" (
    "Id"                   INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "IdAssistenciaTecnica" INTEGER NOT NULL,
    "Nome"                 VARCHAR(255),
    "Documento"            VARCHAR(30),
    "Email"                VARCHAR(255) NOT NULL,
    "Telefone"             VARCHAR(30),
    "Gerente"              BOOLEAN NOT NULL DEFAULT FALSE,
    "Ativo"                BOOLEAN NOT NULL DEFAULT TRUE,
    "SenhaHash"            VARCHAR(255),
    "VersaoSessao"         INTEGER NOT NULL DEFAULT 0,

    CONSTRAINT "PK_IdFuncionario" PRIMARY KEY ("Id"),
    CONSTRAINT "UQ_Funcionario_Id_Assistencia" UNIQUE ("Id", "IdAssistenciaTecnica"),
    CONSTRAINT "UQ_Funcionario_Assistencia_Documento" UNIQUE ("IdAssistenciaTecnica", "Documento"),
    CONSTRAINT "UQ_Funcionario_Assistencia_Email" UNIQUE ("IdAssistenciaTecnica", "Email"),
    CONSTRAINT "FK_AssistenciaTecnica_Funcionario"
        FOREIGN KEY ("IdAssistenciaTecnica")
        REFERENCES public."AssistenciaTecnica" ("Id")
);

CREATE TABLE public."Cliente" (
    "Id"                   INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "IdAssistenciaTecnica" INTEGER NOT NULL,
    "Nome"                 VARCHAR(255) NOT NULL,
    "Documento"            VARCHAR(30),
    "Email"                VARCHAR(255) NOT NULL,
    "Telefone"             VARCHAR(30) NOT NULL,
    "Endereco"             VARCHAR(500),
    "Ativo"                BOOLEAN NOT NULL DEFAULT TRUE,
    "SenhaHash"            VARCHAR(255),
    "VersaoSessao"         INTEGER NOT NULL DEFAULT 0,

    CONSTRAINT "PK_IdCliente" PRIMARY KEY ("Id"),
    CONSTRAINT "UQ_Cliente_Id_Assistencia" UNIQUE ("Id", "IdAssistenciaTecnica"),
    CONSTRAINT "UQ_Cliente_Assistencia_Documento" UNIQUE ("IdAssistenciaTecnica", "Documento"),
    CONSTRAINT "FK_AssistenciaTecnica_Cliente"
        FOREIGN KEY ("IdAssistenciaTecnica")
        REFERENCES public."AssistenciaTecnica" ("Id")
);

CREATE TABLE public."Aparelho" (
    "Id"                   INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "IdAssistenciaTecnica" INTEGER NOT NULL,
    "IdCliente"            INTEGER NOT NULL,
    "Marca"                VARCHAR(100) NOT NULL,
    "Modelo"               VARCHAR(100) NOT NULL,
    "TipoAparelho"         VARCHAR(100),
    "Ativo"                BOOLEAN NOT NULL DEFAULT TRUE,

    CONSTRAINT "PK_IdAparelho" PRIMARY KEY ("Id"),
    CONSTRAINT "UQ_Aparelho_Cliente_Assistencia" UNIQUE ("Id", "IdCliente", "IdAssistenciaTecnica"),
    CONSTRAINT "FK_Cliente_Aparelho"
        FOREIGN KEY ("IdCliente", "IdAssistenciaTecnica")
        REFERENCES public."Cliente" ("Id", "IdAssistenciaTecnica")
);

CREATE TABLE public."Orcamento" (
    "Id"                        INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "IdAssistenciaTecnica"      INTEGER NOT NULL,
    "IdCliente"                 INTEGER NOT NULL,
    "IdAparelho"                INTEGER NOT NULL,
    "IdFuncionario"             INTEGER,
    "Origem"                    VARCHAR(20) NOT NULL,
    "Status"                    VARCHAR(30) NOT NULL DEFAULT 'EmAnalise',
    "DescricaoProblemaCliente"  TEXT NOT NULL,
    "DiagnosticoFuncionario"    TEXT,
    "ValorMaoDeObra"            DECIMAL(15,2),
    "ValorPecas"                DECIMAL(15,2),
    "PrazoConclusao"            DATE,
    "CriadoEm"                  TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "RespondidoEm"              TIMESTAMPTZ,
    "PrazoParaAprovacaoCliente" TIMESTAMPTZ,
    "Ativo"                     BOOLEAN NOT NULL DEFAULT TRUE,
    "AcessoTokenHash"           CHAR(64),

    CONSTRAINT "PK_IdOrcamento" PRIMARY KEY ("Id"),
    CONSTRAINT "UQ_Orcamento_Id_Assistencia" UNIQUE ("Id", "IdAssistenciaTecnica"),
    CONSTRAINT "UQ_Orcamento_AcessoTokenHash" UNIQUE ("AcessoTokenHash"),
    CONSTRAINT "CK_Orcamento_Origem" CHECK ("Origem" IN ('Online', 'LojaImediata', 'LojaPosterior')),
    CONSTRAINT "CK_Orcamento_Status" CHECK ("Status" IN (
        'EmAnalise', 'AguardandoAprovacao', 'Aprovado', 'Recusado', 'Cancelado'
    )),
    CONSTRAINT "CK_Orcamento_Valores" CHECK (
        ("ValorMaoDeObra" IS NULL OR "ValorMaoDeObra" >= 0)
        AND ("ValorPecas" IS NULL OR "ValorPecas" >= 0)
    ),
    CONSTRAINT "FK_Cliente_Orcamento"
        FOREIGN KEY ("IdCliente", "IdAssistenciaTecnica")
        REFERENCES public."Cliente" ("Id", "IdAssistenciaTecnica"),
    CONSTRAINT "FK_Aparelho_Orcamento"
        FOREIGN KEY ("IdAparelho", "IdCliente", "IdAssistenciaTecnica")
        REFERENCES public."Aparelho" ("Id", "IdCliente", "IdAssistenciaTecnica"),
    CONSTRAINT "FK_Funcionario_Orcamento"
        FOREIGN KEY ("IdFuncionario", "IdAssistenciaTecnica")
        REFERENCES public."Funcionario" ("Id", "IdAssistenciaTecnica")
);

CREATE TABLE public."OrdemServico" (
    "Id"                      INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "IdAssistenciaTecnica"    INTEGER NOT NULL,
    "IdOrcamento"             INTEGER NOT NULL,
    "IdFuncionario"           INTEGER NOT NULL,
    "Status"                  VARCHAR(30) NOT NULL,
    "DataAparelhoRecebido"    TIMESTAMPTZ,
    "DataPrevisaoConclusao"   DATE,
    "DataRealConclusao"      TIMESTAMPTZ,
    "DataEntregaAparelho"    TIMESTAMPTZ,

    CONSTRAINT "PK_IdOrdemServico" PRIMARY KEY ("Id"),
    CONSTRAINT "UQ_OrdemServico_Orcamento" UNIQUE ("IdOrcamento"),
    CONSTRAINT "CK_OrdemServico_Status" CHECK ("Status" IN (
        'AguardandoAparelho', 'AguardandoReparo', 'EmReparo', 'ReparoConcluido',
        'Paga', 'Cancelada', 'Desistencia'
    )),
    CONSTRAINT "FK_Orcamento_OrdemServico"
        FOREIGN KEY ("IdOrcamento", "IdAssistenciaTecnica")
        REFERENCES public."Orcamento" ("Id", "IdAssistenciaTecnica"),
    CONSTRAINT "FK_Funcionario_OrdemServico"
        FOREIGN KEY ("IdFuncionario", "IdAssistenciaTecnica")
        REFERENCES public."Funcionario" ("Id", "IdAssistenciaTecnica")
);

CREATE TABLE public."Pagamento" (
    "Id"             INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "IdOrdemServico" INTEGER NOT NULL,
    "Valor"          DECIMAL(15,2) NOT NULL,
    "Data"           TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "RegistradoEm"   TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "FormaPagamento" VARCHAR(100) NOT NULL,

    CONSTRAINT "PK_IdPagamento" PRIMARY KEY ("Id"),
    CONSTRAINT "UQ_Pagamento_OrdemServico" UNIQUE ("IdOrdemServico"),
    CONSTRAINT "CK_Pagamento_Valor" CHECK ("Valor" > 0),
    CONSTRAINT "FK_OrdemServico_Pagamento"
        FOREIGN KEY ("IdOrdemServico")
        REFERENCES public."OrdemServico" ("Id")
);

CREATE TABLE public."ConviteFuncionario" (
    "Id"                   INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "IdAssistenciaTecnica" INTEGER NOT NULL,
    "IdFuncionario"        INTEGER NOT NULL,
    "TokenHash"            CHAR(64) NOT NULL UNIQUE,
    "ExpiraEm"             TIMESTAMPTZ NOT NULL,
    "UsadoEm"              TIMESTAMPTZ,
    FOREIGN KEY ("IdFuncionario", "IdAssistenciaTecnica")
        REFERENCES public."Funcionario" ("Id", "IdAssistenciaTecnica")
);

CREATE TABLE public."RecuperacaoSenha" (
    "Id"                   INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "IdAssistenciaTecnica" INTEGER NOT NULL,
    "IdFuncionario"        INTEGER,
    "IdCliente"            INTEGER,
    "CodigoHash"           CHAR(64) NOT NULL,
    "CriadoEm"             TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "ExpiraEm"             TIMESTAMPTZ NOT NULL,
    "UsadoEm"              TIMESTAMPTZ,
    "Tentativas"           INTEGER NOT NULL DEFAULT 0,
    CONSTRAINT "CK_RecuperacaoSenha_Titular" CHECK (
        ("IdFuncionario" IS NOT NULL AND "IdCliente" IS NULL) OR
        ("IdFuncionario" IS NULL AND "IdCliente" IS NOT NULL)
    ),
    FOREIGN KEY ("IdFuncionario", "IdAssistenciaTecnica")
        REFERENCES public."Funcionario" ("Id", "IdAssistenciaTecnica"),
    FOREIGN KEY ("IdCliente", "IdAssistenciaTecnica")
        REFERENCES public."Cliente" ("Id", "IdAssistenciaTecnica")
);

-- Índices nas consultas previstas: clientes da assistência, orçamentos do
-- cliente e ordens de serviço ligadas aos seus orçamentos.
CREATE INDEX "IX_Cliente_Assistencia" ON public."Cliente" ("IdAssistenciaTecnica");
CREATE UNIQUE INDEX "UQ_Cliente_Assistencia_Email" ON public."Cliente" ("IdAssistenciaTecnica", LOWER("Email"));
CREATE INDEX "IX_Funcionario_Assistencia" ON public."Funcionario" ("IdAssistenciaTecnica");
CREATE INDEX "IX_Orcamento_Cliente" ON public."Orcamento" ("IdAssistenciaTecnica", "IdCliente", "CriadoEm" DESC);
CREATE INDEX "IX_Orcamento_Vencimento" ON public."Orcamento" ("PrazoParaAprovacaoCliente")
    WHERE "Status" = 'AguardandoAprovacao';
CREATE INDEX "IX_OrdemServico_Assistencia" ON public."OrdemServico" ("IdAssistenciaTecnica");
CREATE INDEX "IX_ConviteFuncionario_ExpiraEm" ON public."ConviteFuncionario" ("ExpiraEm");
CREATE INDEX "IX_RecuperacaoSenha_ExpiraEm" ON public."RecuperacaoSenha" ("ExpiraEm");

COMMIT;
